findings.codeql_raw_query:
/**
 * @name HTTP response splitting via CRLF injection
 * @description User-controlled data containing CRLF sequences flowing into HTTP response headers
 * @kind path-problem
 * @problem.severity error
 * @id py/http-response-splitting
 * @tags security
 *        external/cwe/cwe-113
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ResponseSplittingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for HTTP header construction in h11
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("h11").getMember("_events").getMember("Response").getACall() or
      call = API::moduleImport("h11").getMember("_events").getMember("InformationalResponse").getACall()
    |
      // Check if source data flows into headers argument (position 1)
      sink = call.getArg(1)
    )
  }
}

module ResponseSplittingFlow = TaintTracking::Global<ResponseSplittingConfig>;
import ResponseSplittingFlow::PathGraph

from ResponseSplittingFlow::PathNode source, ResponseSplittingFlow::PathNode sink
where ResponseSplittingFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "HTTP response splitting vulnerability from $@.", source.getNode(), "user input"
